test('renderInvoiceText shows VAT line', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 50 }], // 5000, discount 2500, amount 2500, vat 525
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  assert.match(text, /VAT: €5.25/); // 2500 * 21 / 100
  assert.match(text, /Total: €30.25/); // 5000 - 2500 + 525
});

test('renderInvoiceText handles multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  const lines = text.split('\n');
  // Should have: number line, customer line, 2 item lines, VAT line, total line = 6
  assert.equal(lines.length, 6);
  assert.match(lines[2], /2 Development \(hour\)/);
  assert.match(lines[3], /1 Logo package/);
});

test('renderInvoiceText returns CUSTOMER_NOT_FOUND for missing customer', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2025-12-15',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
  };

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, false);
  assert.equal(renderResult.error, 'CUSTOMER_NOT_FOUND');
});

test('renderInvoiceText formats all amounts as euros', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'STICKER', qty: 3 }], // 3 * 50 cents = 150 cents = €1.50
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // Should show €0.50 for unit price and €1.50 for total
  assert.match(text, /€0.50/);
  assert.match(text, /€1.50/);
});

test('renderInvoiceText displays line total correctly for each line', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'COPY-HOUR', qty: 3 }, // 3 * 6000 = 18000 cents = €180.00
      { sku: 'HOST-MONTH', qty: 2 }, // 2 * 1500 = 3000 cents = €30.00
    ],
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  assert.match(text, /3 Copywriting \(hour\).*€180.00/);
  assert.match(text, /2 Website hosting \(month\).*€30.00/);
  // 18000 + 3000 = 21000, VAT: 21000 * 21 / 100 = 4410
  assert.match(text, /VAT: €44.10/);
  assert.match(text, /Total: €254.10/);
});

test('renderInvoiceText sums line totals correctly for total', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'COPY-HOUR', qty: 2 }, // 2 * 6000 = 12000
      { sku: 'SUPPORT-HOUR', qty: 2 }, // 2 * 7250 = 14500
    ],
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // 12000 + 14500 = 26500, VAT: 26500 * 21 / 100 = 5565
  assert.match(text, /VAT: €55.65/);
  assert.match(text, /Total: €320.65/); // 26500 + 5565 = 32065
});

test('renderInvoiceText line format is consistent', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 2 },
    ],
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  const lines = text.split('\n');
  // Should have: number, customer, 2 items, VAT, total = 6 lines
  assert.equal(lines.length, 6);
  // Each line item should have 4 parts: qty name price total
  const line1Parts = lines[2].split(' ').filter(p => p); // First item line
  const line2Parts = lines[3].split(' ').filter(p => p); // Second item line
  // Both should have similar structure (qty at start, euro amounts at end)
  assert(line1Parts[0] === '1');
  assert(line2Parts[0] === '2');
  assert(line1Parts[line1Parts.length - 1].startsWith('€'));
  assert(line2Parts[line2Parts.length - 1].startsWith('€'));
});

test('renderInvoiceText works with large quantities', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'STICKER', qty: 1000 }], // 1000 * 50 = 50000 cents
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  assert.match(text, /1000 Sticker sheet/);
  // 50000, VAT: 50000 * 21 / 100 = 10500
  assert.match(text, /VAT: €105.00/);
  assert.match(text, /Total: €605.00/);
});

test('renderInvoiceText shows line discount amount', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }], // 95000, discount 9500
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // Should show discount info on the line
  assert.match(text, /10% off: €95.00/);
});

test('renderInvoiceText shows multiple lines with different discounts', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 2, discountPercent: 10 }, // 19000, discount 1900
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }, // no discount shown
    ],
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // First line should show discount
  assert.match(text, /2 Development \(hour\).*10% off: €19.00/);
  // Second line should not show discount info
  assert.match(text, /1 Logo package/);
});

test('renderInvoiceText shows voucher line before total', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500, VAT 1995, total 11495
  });

  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, { code: 'WELCOME10', amount: 1000 });
  invoice = voucherResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  const lines = text.split('\n');

  // Should have: number, customer, item, VAT, voucher, total
  assert.match(text, /Voucher: €10.00/);

  // Voucher should appear before total
  const voucherLineIdx = lines.findIndex(l => l.includes('Voucher'));
  const totalLineIdx = lines.findIndex(l => l.includes('Total'));
  assert(voucherLineIdx < totalLineIdx, 'Voucher line should appear before Total line');
});

test('renderInvoiceText shows due date when invoice has one', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  let invoice = result.value;
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // Draft invoices don't have dueDate assigned, but issued ones do
  assert.match(text, /Due: 2026-01-14/);
});

test('renderInvoiceText does not show due date for draft invoices', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const invoice = result.value;
  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // Draft should not show due date
  assert(!text.includes('Due:'), 'Draft invoice should not show Due line');
});

test('renderInvoiceText shows paid amount when invoice has payments', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // 19000, VAT 3990, total 22990
  });

  let invoice = result.value;
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  const paymentResult = recordPayment(invoice, { amount: 10000, date: '2025-12-20' });
  invoice = paymentResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  assert.match(text, /Paid: €100.00/);
});

test('renderInvoiceText shows total paid amount with multiple payments', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // total 22990
  });

  let invoice = result.value;
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  let paymentResult = recordPayment(invoice, { amount: 10000, date: '2025-12-20' });
  invoice = paymentResult.value;

  paymentResult = recordPayment(invoice, { amount: 5000, date: '2025-12-25' });
  invoice = paymentResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // 10000 + 5000 = 15000 cents = €150.00
  assert.match(text, /Paid: €150.00/);
});

test('renderInvoiceText does not show paid line for invoices without payments', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  let invoice = result.value;
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  assert(!text.includes('Paid:'), 'Invoice without payments should not show Paid line');
});

test('renderInvoiceText shows all enhancements together', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // 47500, discount 4750
      { sku: 'LOGO-PACK', qty: 2 }, // no line discount
    ],
    terms: 'NET14',
  });

  let invoice = result.value;

  // Add voucher
  const voucherResult = applyVoucher(invoice, { code: 'PROMO', amount: 5000 });
  invoice = voucherResult.value;

  // Issue invoice
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  // Add payment
  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2025-12-20' });
  invoice = paymentResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  const lines = text.split('\n');

  // Should show all components
  assert.match(text, /10% off: €47.50/); // line discount
  assert.match(text, /Voucher: €50.00/); // voucher
  assert.match(text, /Due: 2025-12-29/); // due date
  assert.match(text, /Paid: €500.00/); // paid amount

  // Verify order: items, VAT, voucher, total, due, paid
  const voucherIdx = lines.findIndex(l => l.includes('Voucher'));
  const totalIdx = lines.findIndex(l => l.startsWith('Total'));
  const dueIdx = lines.findIndex(l => l.includes('Due:'));
  const paidIdx = lines.findIndex(l => l.includes('Paid:'));

  assert(voucherIdx < totalIdx, 'Voucher should appear before Total');
  assert(totalIdx < dueIdx, 'Total should appear before Due');
  assert(dueIdx < paidIdx, 'Due should appear before Paid');
});

