});

test('renderInvoiceText shows paid amount when invoice has payments', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // 19000, VAT 3990, total 22990
  });

  let invoice = result.value;
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  const paymentResult = recordPayment(invoice, { amount: 10000, date: '2025-12-20' });
  invoice = paymentResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  assert.match(text, /Paid: €100.00/);
});

test('renderInvoiceText shows total paid amount with multiple payments', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // total 22990
  });

  let invoice = result.value;
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  let paymentResult = recordPayment(invoice, { amount: 10000, date: '2025-12-20' });
  invoice = paymentResult.value;

  paymentResult = recordPayment(invoice, { amount: 5000, date: '2025-12-25' });
  invoice = paymentResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  // 10000 + 5000 = 15000 cents = €150.00
  assert.match(text, /Paid: €150.00/);
});

test('renderInvoiceText does not show paid line for invoices without payments', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  let invoice = result.value;
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  assert(!text.includes('Paid:'), 'Invoice without payments should not show Paid line');
});

test('renderInvoiceText shows all enhancements together', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // 47500, discount 4750
      { sku: 'LOGO-PACK', qty: 2 }, // no line discount
    ],
    terms: 'NET14',
  });

  let invoice = result.value;

  // Add voucher
  const voucherResult = applyVoucher(invoice, { code: 'PROMO', amount: 5000 });
  invoice = voucherResult.value;

  // Issue invoice
  const issueResult = issueInvoice(invoice, []);
  invoice = issueResult.value;

  // Add payment
  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2025-12-20' });
  invoice = paymentResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  const lines = text.split('\n');

  // Should show all components
  assert.match(text, /10% off: €47.50/); // line discount
  assert.match(text, /Voucher: €50.00/); // voucher
  assert.match(text, /Due: 2025-12-29/); // due date
  assert.match(text, /Paid: €500.00/); // paid amount

  // Verify order: items, VAT, voucher, total, due, paid
  const voucherIdx = lines.findIndex(l => l.includes('Voucher'));
  const totalIdx = lines.findIndex(l => l.startsWith('Total'));
  const dueIdx = lines.findIndex(l => l.includes('Due:'));
  const paidIdx = lines.findIndex(l => l.includes('Paid:'));

  assert(voucherIdx < totalIdx, 'Voucher should appear before Total');
  assert(totalIdx < dueIdx, 'Total should appear before Due');
  assert(dueIdx < paidIdx, 'Due should appear before Paid');
});

