test('renderInvoiceText shows voucher line before total', () => {
  let result = createInvoice({
    customerId: 'C-002', // Standard tier (no discount)
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500, VAT 1995, total 11495
  });

  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, { code: 'WELCOME10', amount: 1000 });
  invoice = voucherResult.value;

  const renderResult = renderInvoiceText(invoice);

  assert.equal(renderResult.ok, true);
  const text = renderResult.value;
  const lines = text.split('\n');

  // Should have: number, customer, item, VAT, voucher, total
  assert.match(text, /Voucher: €10.00/);

  // Voucher should appear before total
  const voucherLineIdx = lines.findIndex(l => l.includes('Voucher'));
  const totalLineIdx = lines.findIndex(l => l.includes('Total'));
  assert(voucherLineIdx < totalLineIdx, 'Voucher line should appear before Total line');
});

